import re

def _find_node(doc, scope, title_pattern, kind=None):
    for n in scope_nodes(doc, scope):
        if title_pattern in n.get("title", ""):
            if kind is None or n.get("kind") == kind:
                return n
    return None

def _find_nodes(doc, scope, title_pattern, kind=None):
    results = []
    for n in scope_nodes(doc, scope):
        if title_pattern in n.get("title", ""):
            if kind is None or n.get("kind") == kind:
                results.append(n)
    return results

def entities(doc, scope):
    products_table = _find_node(doc, scope, ": Products", kind="table")
    if not products_table:
        return []
    products = []
    for row_idx, row in table_rows(products_table):
        prod_id = row["product"]
        group = row["group"]
        sub_group = row["sub-group"]
        products.append({"id": prod_id, "description": f"{prod_id} ({group}/{sub_group})"})
    return products

def recorded_end(doc, scope):
    ledger_table = _find_node(doc, scope, ": Daily ledger", kind="table")
    if not ledger_table:
        return None
    rows = table_rows(ledger_table)
    if not rows:
        return None
    return float(rows[-1][1]["day"])

def inputs(doc, scope):
    products_table = _find_node(doc, scope, ": Products", kind="table")
    ledger_table = _find_node(doc, scope, ": Daily ledger", kind="table")
    order_book_future = _find_node(doc, scope, "Orders received and production planned", kind="table")

    result = []

    if products_table:
        for row_idx, row in table_rows(products_table):
            result.append({
                "id": f"opening_stock_{row['product']}",
                "time": None,
                "kind": "opening_stock",
                "entities": [row["product"]],
                "fields": {"opening_stock": int(row["opening stock"])},
                "src": [[products_table["node_id"], row_idx, ["product", "opening stock"]]]
            })

    if ledger_table:
        for row_idx, row in table_rows(ledger_table):
            day = int(row["day"])
            product = row["product"]
            result.append({
                "id": f"production_{product}_{day}",
                "time": float(day),
                "kind": "production",
                "entities": [product],
                "fields": {"produced": int(row["produced"])},
                "src": [[ledger_table["node_id"], row_idx, ["day", "product", "produced"]]]
            })
            result.append({
                "id": f"order_{product}_{day}",
                "time": float(day),
                "kind": "order",
                "entities": [product],
                "fields": {"ordered": int(row["ordered"])},
                "src": [[ledger_table["node_id"], row_idx, ["day", "product", "ordered"]]]
            })

    if order_book_future:
        for row_idx, row in table_rows(order_book_future):
            day = int(row["day"])
            product = row["product"]
            result.append({
                "id": f"future_order_{product}_{day}",
                "time": float(day),
                "kind": "future_order",
                "entities": [product],
                "fields": {"ordered": int(row["ordered"])},
                "src": [[order_book_future["node_id"], row_idx, ["day", "date", "product", "ordered"]]]
            })
            result.append({
                "id": f"future_production_{product}_{day}",
                "time": float(day),
                "kind": "future_production",
                "entities": [product],
                "fields": {"planned_production": int(row["planned production"])},
                "src": [[order_book_future["node_id"], row_idx, ["day", "date", "product", "planned production"]]]
            })

    return result

def outcomes(doc, scope):
    ledger_table = _find_node(doc, scope, ": Daily ledger", kind="table")
    results = []
    valid_ids = {e["id"] for e in entities(doc, scope)}

    if ledger_table:
        for row_idx, row in table_rows(ledger_table):
            product = row["product"]
            if product not in valid_ids:
                continue
            day = int(row["day"])
            results.append({
                "time": float(day),
                "kind": "shipped",
                "entities": [product],
                "value": int(row["shipped"]),
                "src": [[ledger_table["node_id"], row_idx, ["day", "product", "shipped"]]]
            })
            results.append({
                "time": float(day),
                "kind": "backordered",
                "entities": [product],
                "value": int(row["backordered"]),
                "src": [[ledger_table["node_id"], row_idx, ["day", "product", "backordered"]]]
            })
            results.append({
                "time": float(day),
                "kind": "stock",
                "entities": [product],
                "value": int(row["stock"]),
                "src": [[ledger_table["node_id"], row_idx, ["day", "product", "stock"]]]
            })

    open_orders_table = _find_node(doc, scope, "Open orders at the end of day", kind="table")
    order_book_list = _find_node(doc, scope, ": Order book", kind="list")
    order_book_lines_src = []
    if order_book_list and order_book_list.get("lines"):
        order_book_lines_src = [[order_book_list["node_id"], i] for i in range(len(order_book_list["lines"]))]

    list_lines_added = False
    if open_orders_table:
        for row_idx, row in table_rows(open_orders_table):
            product = row["product"]
            if product not in valid_ids:
                continue
            src = [[open_orders_table["node_id"], row_idx, ["product", "day placed", "units still open"]]]
            if not list_lines_added and order_book_lines_src:
                src.extend(order_book_lines_src)
                list_lines_added = True
            results.append({
                "time": None,
                "kind": "open_order_end_of_period",
                "entities": [product],
                "value": int(row["units still open"]),
                "src": src
            })

    if not list_lines_added and order_book_lines_src:
        results.append({
            "time": None,
            "kind": "period_end_state",
            "entities": [],
            "value": None,
            "src": order_book_lines_src
        })

    events_nodes = _find_nodes(doc, scope, ": Events")
    prod_pattern = re.compile(r'\b([A-Z]{3}\d{2}[A-Z]\d{2}[A-Z][A-Z0-9-]*)\b')

    for events_node in events_nodes:
        if events_node.get("kind") == "text":
            lines = events_node.get("text", "").split('\n')
        else:
            lines = events_node.get("lines", [])

        if not lines:
            continue
        if len(lines) == 1 and "No events" in lines[0]:
            continue

        for line_idx, line in enumerate(lines):
            day_match = re.match(r'Day (\d+)', line)
            if not day_match:
                continue
            day = int(day_match.group(1))
            matches = [m for m in prod_pattern.findall(line) if m in valid_ids]
            entities_list = matches if matches else []

            if "runs out of stock" in line:
                event_kind = "runs_out_of_stock"
            elif "fully backordered" in line:
                event_kind = "fully_backordered"
            elif "backlog is cleared" in line or "backlog was cleared" in line:
                event_kind = "backlog_cleared"
            elif "dispatch capacity" in line or "capacity was reached" in line:
                event_kind = "capacity_reached"
            elif "ships in full" in line:
                event_kind = "shipped_in_full"
            else:
                event_kind = "event"

            results.append({
                "time": float(day),
                "kind": event_kind,
                "entities": entities_list,
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })

    return results

def params(doc, scope):
    for n in scope_nodes(doc, scope):
        if n.get("kind") == "text":
            text = n.get("text", "")
            match = re.search(r'capacity:\s*(\d+)', text)
            if match:
                return {"daily_dispatch_capacity_kg": int(match.group(1))}
    return {}


