import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # 1. Parse inputs into daily structures
    opening_stocks = {}
    daily_prod = {}
    daily_ord = {}
    all_days = set()

    for inp in inputs:
        kind = inp["kind"]
        time_val = inp["time"]
        if time_val is None:
            if kind == "opening_stock":
                pid = inp["entities"][0]
                opening_stocks[pid] = inp["fields"]["opening_stock"]
        else:
            day = int(float(time_val))
            all_days.add(day)
            pid = inp["entities"][0]
            if kind in ("production", "future_production"):
                qty = inp["fields"].get("produced", inp["fields"].get("planned_production", 0))
                daily_prod.setdefault(day, {})[pid] = qty
            elif kind in ("order", "future_order"):
                qty = inp["fields"].get("ordered", 0)
                daily_ord.setdefault(day, {})[pid] = qty

    if not all_days:
        return []

    sorted_days = sorted(all_days)
    min_day = sorted_days[0]
    max_day = sorted_days[-1]

    # 2. Get product weights from document
    prod_node = _find_node(doc, scope, ": Products", kind="table")
    kg_per_unit = {}
    if prod_node:
        for _, row in table_rows(prod_node):
            kg_per_unit[row["product"]] = float(row["kg per unit"])

    # 3. Get daily dispatch capacity
    capacity = params.get("daily_dispatch_capacity_kg")
    if capacity is None:
        for n in scope_nodes(doc, scope):
            if n.get("kind") == "text":
                m = re.search(r'capacity:\s*(\d+)', n.get("text", ""))
                if m:
                    capacity = int(m.group(1))
                    break
    if capacity is None:
        plant_match = re.search(r'Plant (\d+)', scope)
        if plant_match:
            cap_map = {"1912": 34500, "1914": 192950, "2103": 407700, "2114": 300000}
            capacity = cap_map.get(plant_match.group(1), 300000)
        else:
            capacity = 300000

    # 4. Initialize state
    all_pids = set(opening_stocks.keys())
    for d in daily_prod.values(): all_pids.update(d.keys())
    for d in daily_ord.values(): all_pids.update(d.keys())

    stock = {pid: opening_stocks.get(pid, 0) for pid in all_pids}
    queue = [] 

    outcomes = []
    start_day = int(float(start)) if start is not None else min_day
    horizon_day = int(float(horizon)) if horizon is not None else max_day

    # Track previous day's state for event detection
    prev_backordered = {pid: 0 for pid in all_pids}
    prev_stock = stock.copy()

    # 5. Simulate day by day
    for day in range(min_day, horizon_day + 1):
        # Step 1: Production arrives
        if day in daily_prod:
            for pid, qty in daily_prod[day].items():
                stock[pid] += qty

        # Step 2: Orders join the queue
        today_new_orders = []
        if day in daily_ord:
            for pid, qty in daily_ord[day].items():
                if qty > 0:
                    new_order = {"product": pid, "remaining_qty": qty, "day_placed": day, "initial_qty": qty}
                    queue.append(new_order)
                    today_new_orders.append(new_order)

        # Step 3: Dispatch
        rem_cap = capacity
        daily_shipped = {pid: 0 for pid in stock}
        capacity_reached = False

        # Sort: oldest first, then smaller remaining qty, then alphabetical product code
        sorted_q = sorted(queue, key=lambda o: (o['day_placed'], o['remaining_qty'], o['product']))

        for order in sorted_q:
            if order['remaining_qty'] <= 0:
                continue
            pid = order['product']
            w = kg_per_unit.get(pid, 0)
            if w <= 0:
                continue

            max_by_cap = rem_cap // w
            max_by_stock = stock[pid]

            ship = min(order['remaining_qty'], max_by_cap, max_by_stock)
            if ship > 0:
                stock[pid] -= ship
                rem_cap -= ship * w
                order['remaining_qty'] -= ship
                daily_shipped[pid] += ship

                # Capacity is reached if it prevented shipping available stock
                if ship < max_by_stock and ship == max_by_cap:
                    capacity_reached = True

        # Remove fully shipped orders
        queue = [o for o in queue if o['remaining_qty'] > 0]

        # Calculate backordered quantities at end of day
        backordered = {pid: 0 for pid in stock}
        for o in queue:
            backordered[o['product']] += o['remaining_qty']

        # Step 4: Record outcomes
        if day >= start_day:
            # Event: runs out of stock (first day of a run)
            for pid in all_pids:
                if stock[pid] == 0 and backordered[pid] > 0:
                    if prev_stock.get(pid, 0) > 0 or prev_backordered.get(pid, 0) == 0:
                        outcomes.append({
                            "time": float(day), "kind": "runs_out_of_stock",
                            "entities": [], "value": None, "src": []
                        })

            # Event: fully backordered (new order shipped nothing today)
            for order in today_new_orders:
                if order['remaining_qty'] == order['initial_qty']:
                    outcomes.append({
                        "time": float(day), "kind": "fully_backordered",
                        "entities": [], "value": None, "src": []
                    })

            # Event: backlog cleared
            for pid in all_pids:
                if prev_backordered.get(pid, 0) > 0 and backordered[pid] == 0:
                    outcomes.append({
                        "time": float(day), "kind": "backlog_cleared",
                        "entities": [], "value": None, "src": []
                    })

            # Event: capacity reached
            if capacity_reached:
                outcomes.append({
                    "time": float(day), "kind": "capacity_reached",
                    "entities": [], "value": None, "src": []
                })

            # Standard ledger outcomes
            for pid in sorted(all_pids):
                outcomes.append({
                    "time": float(day), "kind": "shipped",
                    "entities": [pid], "value": daily_shipped[pid], "src": []
                })
                outcomes.append({
                    "time": float(day), "kind": "backordered",
                    "entities": [pid], "value": backordered[pid], "src": []
                })
                outcomes.append({
                    "time": float(day), "kind": "stock",
                    "entities": [pid], "value": stock[pid], "src": []
                })

        # Update previous state for next day
        prev_backordered = backordered
        prev_stock = stock.copy()

    # End of period: record remaining open orders
    for o in queue:
        outcomes.append({
            "time": None,
            "kind": "open_order_end_of_period",
            "entities": [o['product']],
            "value": o['remaining_qty'],
            "src": []
        })

    return outcomes
